-- Phase 1, metadata only. Execute only after separate read-only authorization.
-- No rows, function bodies, defaults, policy expressions or migration statements.
begin read only;
select jsonb_pretty(jsonb_build_object(
 'schemas',(select jsonb_agg(nspname order by nspname) from pg_namespace where nspname in ('public','private','auth')),
 'extensions',(select jsonb_agg(jsonb_build_object('name',extname,'version',extversion) order by extname) from pg_extension),
 'relations',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',c.relname,'kind',c.relkind,'rls',c.relrowsecurity,'forcedRls',c.relforcerowsecurity,'acl',c.relacl::text) order by n.nspname,c.relname) from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private') and c.relkind in ('r','p','v','m','S')),
 'columns',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',a.attname,'position',a.attnum,'type',format_type(a.atttypid,a.atttypmod),'notNull',a.attnotnull,'identity',a.attidentity,'generated',a.attgenerated,'defaultHash',md5(pg_get_expr(d.adbin,d.adrelid))) order by n.nspname,c.relname,a.attnum) from pg_attribute a join pg_class c on c.oid=a.attrelid join pg_namespace n on n.oid=c.relnamespace left join pg_attrdef d on d.adrelid=c.oid and d.adnum=a.attnum where n.nspname in ('public','private') and a.attnum>0 and not a.attisdropped and c.relkind in ('r','p','v','m')),
 'constraints',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',k.conname,'type',k.contype,'validated',k.convalidated,'definitionHash',md5(pg_get_constraintdef(k.oid))) order by n.nspname,c.relname,k.conname) from pg_constraint k join pg_class c on c.oid=k.conrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
 'indexes',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',x.relname,'unique',i.indisunique,'valid',i.indisvalid,'definitionHash',md5(pg_get_indexdef(i.indexrelid))) order by n.nspname,c.relname,x.relname) from pg_index i join pg_class c on c.oid=i.indrelid join pg_class x on x.oid=i.indexrelid join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private')),
 'functions',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'name',p.proname,'identityArguments',pg_get_function_identity_arguments(p.oid),'returns',pg_get_function_result(p.oid),'securityDefiner',p.prosecdef,'language',l.lanname,'acl',p.proacl::text,'definitionHash',md5(pg_get_functiondef(p.oid))) order by n.nspname,p.proname,p.oid) from pg_proc p join pg_namespace n on n.oid=p.pronamespace join pg_language l on l.oid=p.prolang where n.nspname in ('public','private') and p.prokind in ('f','p')),
 'triggers',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'table',c.relname,'name',t.tgname,'enabled',t.tgenabled,'function',t.tgfoid::regprocedure::text,'definitionHash',md5(pg_get_triggerdef(t.oid))) order by n.nspname,c.relname,t.tgname) from pg_trigger t join pg_class c on c.oid=t.tgrelid join pg_namespace n on n.oid=c.relnamespace where not t.tgisinternal and (n.nspname in ('public','private') or (n.nspname='auth' and c.relname='users'))),
 'policies',(select jsonb_agg(jsonb_build_object('schema',schemaname,'table',tablename,'name',policyname,'command',cmd,'roles',roles,'permissive',permissive,'usingHash',md5(qual),'checkHash',md5(with_check)) order by schemaname,tablename,policyname) from pg_policies where schemaname in ('public','private')),
 'defaultPrivileges',(select jsonb_agg(jsonb_build_object('schema',n.nspname,'kind',a.defaclobjtype,'acl',a.defaclacl::text) order by n.nspname,a.defaclobjtype) from pg_default_acl a left join pg_namespace n on n.oid=a.defaclnamespace where n.nspname in ('public','private') or a.defaclnamespace=0)
));
rollback;
